def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if not points:
        return out

    top = min(r for r, c in points)
    bottom = max(r for r, c in points)
    left = min(c for r, c in points)
    right = max(c for r, c in points)
    original_size = min(bottom - top + 1, right - left + 1)

    color = 2
    while True:
        nt, nb = top + 2, bottom - 2
        nl, nr = left + 2, right - 2
        height, width = nb - nt + 1, nr - nl + 1

        # A singleton center is used for the larger frames.
        if height == 1 and width == 1 and original_size >= 15:
            for r in range(top + 1, bottom):
                for c in range(left + 1, right):
                    out[r][c] = color
            out[nt][nl] = 5
            break

        if height < 2 or width < 2:
            for r in range(top + 1, bottom):
                for c in range(left + 1, right):
                    out[r][c] = color
            break

        # Fill the band inside the current frame, leaving the next frame clear.
        for r in range(top + 1, bottom):
            for c in range(left + 1, right):
                if not (nt <= r <= nb and nl <= c <= nr):
                    out[r][c] = color

        for c in range(nl, nr + 1):
            out[nt][c] = 5
            out[nb][c] = 5
        for r in range(nt, nb + 1):
            out[r][nl] = 5
            out[r][nr] = 5

        top, bottom, left, right = nt, nb, nl, nr
        color = 0 if color == 2 else 2

    return out
